<?php require_once __DIR__.'/../../app/layout.php';$a=require_admin();function process_payment(PDO $pdo,array $a,string $table,string $type):void{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['action']==='approve'?'approved':'rejected';$pdo->prepare("UPDATE $table SET status=?,approved_by=?,approved_at=NOW(),remarks=? WHERE id=? AND status='pending'")->execute([$status,$a['id'],trim($_POST['remarks']??''),$id]);if($status==='approved'){$p=$pdo->prepare("SELECT member_id,amount FROM $table WHERE id=?");$p->execute([$id]);$r=$p->fetch();$prefix=$type==='membership'?'MEM':'DON';$no=$prefix.'/'.date('Y').'/'.str_pad((string)$id,6,'0',STR_PAD_LEFT);$pdo->prepare('INSERT IGNORE INTO acknowledgements (acknowledgement_no,member_id,payment_type,source_id,amount,issued_at) VALUES (?,?,?,?,?,NOW())')->execute([$no,$r['member_id'],$type,$id,$r['amount']]);}audit($pdo,$a['id'],$type.'_payment_'.$status,$type,$id);flash('Payment '.$status.'.');redirect('/admin/'.($type==='membership'?'payments':'donations').'.php');}}
process_payment($pdo,$a,'membership_payments','membership');$rows=$pdo->query('SELECT p.*,m.full_name,m.member_id FROM membership_payments p JOIN members m ON m.id=p.member_id ORDER BY p.created_at DESC')->fetchAll();header_html('Membership payments');?><h1>Membership payments</h1><table><tr><th>Member</th><th>Amount</th><th>Transaction</th><th>Status</th><th>Verify</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['amount'])?></td><td><?=e($r['transaction_no'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input name="remarks" placeholder="Remarks"><button name="action" value="approve">Approve</button><button name="action" value="reject">Reject</button></form><?php endif;?></td></tr><?php endforeach;?></table><?php footer_html();
